def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def put(name,value):(out/name).write_text(json.dumps(value,indent=2)+'\n')
def git(*args):return subprocess.check_output(['git',*args],cwd=repo)
