assert not any(p.startswith('common/') for p in new)
production=[p for p in files if '/tests/' not in p and not p.startswith('tests/')]
for p in files:
    target=out/'source'/p;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(repo/p,target)
patch=git('diff','--binary')
for p in new:
    r=subprocess.run(['git','diff','--no-index','--binary','--','/dev/null',p],cwd=repo,stdout=subprocess.PIPE);assert r.returncode==1;patch+=r.stdout
(out/'b5.patch').write_bytes(patch)
subprocess.run(['git','apply','--reverse','--check',str(out/'b5.patch')],cwd=repo,check=True)
check=subprocess.run(['git','diff','--check'],cwd=repo,capture_output=True,text=True);assert check.returncode==0
